		public int TargetType { get; set; }

		[ProtoMember(26)]
		public int TargetPrefer { get; set; }

		[ProtoMember(27)]
		public int Damage { get; set; }

		[ProtoMember(28)]
		public int[] DamageFactor { get; set; }

		[ProtoMember(29)]
		public int DamageAddFactor { get; set; }

		[ProtoMember(30)]
		[BsonDictionaryOptions(/*Could not decode attribute arguments.*/)]
		public Dictionary<int, long> Stats { get; set; }

		[ProtoMember(31)]
		public int[] Triggers { get; set; }

		[ProtoMember(32)]
		public int[] SkillTag { get; set; }

		public SkillTriggerConfig GetTriggerByType(int triggerType)
		{
			if (!triggerInit)
			{
				triggerInit = true;
				int[] triggers = Triggers;
				if (triggers != null && triggers.Length != 0)
				{
					triggerConfigs = new Dictionary<int, SkillTriggerConfig>();
					int[] triggers2 = Triggers;
					foreach (int num in triggers2)
					{
						if (!ConfigSingleton<SkillTriggerConfigCategory>.Instance.Contain(num))
						{
							Log.Error($"主动技能触发器不存在! 技能: {Id}, ID: {num}");
							continue;
						}
						SkillTriggerConfig skillTriggerConfig = ConfigSingleton<SkillTriggerConfigCategory>.Instance.Get(num);
						if (!triggerConfigs.TryAdd(skillTriggerConfig.Type, skillTriggerConfig))
						{
							Log.Error($"主动技能触发器重复! 技能: {Id}, 重复ID: {num}");
						}
					}
				}
			}
			return triggerConfigs?.GetValueOrDefault(triggerType);
		}
	}
