	[ProtoContract]
	public class ActiveSkillMotionConfig : ProtoObject, IConfig
	{
		public class Effect
		{
			public int Point;

			public int EffectId;
		}

		public const int TP_START_CAST = 1;

		public const int TP_FINISH_CAST = 2;

		public const int TP_ATK_OR_HEAL_TARGET = 3;

		public const int PNT_CASTER = 1;

		public const int PNT_TARGET = 2;

		public const int PNT_CASTER_POS = 3;

		public const int PNT_TARGET_POS = 4;

		private UnOrderMultiMap<int, Effect> time_pntEffects = new UnOrderMultiMap<int, Effect>();

		[ProtoMember(1)]
		public int Id { get; set; }

		[ProtoMember(2)]
		public int SkillId { get; set; }

		[ProtoMember(3)]
		public int Model { get; set; }

		[ProtoMember(4)]
		public bool IsDefault { get; set; }

		[ProtoMember(5)]
		public Array<int>[] Effects { get; set; }

		[ProtoMember(6)]
		public int Bullet { get; set; }

		public override void AfterEndInit()
		{
			((Dictionary<int, List<Effect>>)(object)time_pntEffects).Clear();
			if (Effects == null)
			{
				return;
			}
			Array<int>[] effects = Effects;
			foreach (Array<int> obj in effects)
			{
				int valueOrDefault = obj.Values.GetValueOrDefault(0, 0);
				int valueOrDefault2 = obj.Values.GetValueOrDefault(1, 0);
				int valueOrDefault3 = obj.Values.GetValueOrDefault(2, 0);
				if (valueOrDefault != 0 && valueOrDefault2 != 0 && valueOrDefault3 != 0)
				{
					time_pntEffects.Add(valueOrDefault, new Effect
					{
						Point = valueOrDefault2,
						EffectId = valueOrDefault3
					});
				}
			}
		}

		public List<Effect> GetEffects(int timePoint)
		{
			return ((IReadOnlyDictionary<int, List<Effect>>)time_pntEffects).GetValueOrDefault(timePoint);
		}
	}
