			foreach (var (id, collection) in (SortedDictionary<int, List<BeastSoulConfig>>)(object)soulType_soulConfigs)
			{
				if (ConfigSingleton<BeastSoulTypeConfigCategory>.Instance.Get(id).BeastType == beastType)
				{
					list.AddRange(collection);
				}
			}
			return list;
		}

