		private Dictionary<int, EquipPowerConfig> dict = new Dictionary<int, EquipPowerConfig>();

		[BsonElement]
		[ProtoMember(1)]
		private List<EquipPowerConfig> list = new List<EquipPowerConfig>();

		[ProtoIgnore]
		[BsonIgnore]
		private Dictionary<int, Dictionary<int, int>> _CacheMaxLevel = new Dictionary<int, Dictionary<int, int>>();

		[ProtoIgnore]
		[BsonIgnore]
		private Dictionary<int, Dictionary<int, EquipPowerConfig>> _CachePowerLevelConfigs = new Dictionary<int, Dictionary<int, EquipPowerConfig>>();

		public EquipPowerConfigCategory(List<EquipPowerConfig> list)
		{
			this.list = list;
		}

		public EquipPowerConfigCategory()
		{
		}

		public void Merge(object o)
		{
			EquipPowerConfigCategory equipPowerConfigCategory = o as EquipPowerConfigCategory;
			list.AddRange(equipPowerConfigCategory.list);
