			foreach (EquipPowerConfig item in s.list)
			{
				dict[item.Id] = item;
				((ProtoObject)item).AfterEndInit();
			}
			((ProtoObject)this).AfterEndInit();
		}

		[ProtoAfterDeserialization]
		public void ProtoEndInit()
		{
			foreach (EquipPowerConfig item in list)
			{
				((ProtoObject)item).AfterEndInit();
				dict.Add(item.Id, item);
			}
			((ProtoObject)this).AfterEndInit();
		}

		public EquipPowerConfig Get(int id)
		{
			dict.TryGetValue(id, out var value);
			if (value == null)
			{
				Log.Info(string.Format("配置找不到，配置表名: {0}，配置id: {1}", "EquipPowerConfig", id));
			}
			return value;
		}

		public bool Contain(int id)
		{
			return dict.ContainsKey(id);
		}

		public Dictionary<int, EquipPowerConfig> GetAll()
		{
			return dict;
		}

		public List<EquipPowerConfig> GetList()
		{
			return list;
		}

		public EquipPowerConfig GetOne()
		{
			if (dict == null || dict.Count <= 0)
			{
				return null;
			}
			return list[0];
		}

		public int GetMaxLevel(int job, int part)
		{
			if (!_CacheMaxLevel.TryGetValue(job, out var value))
			{
				value = new Dictionary<int, int>();
				_CacheMaxLevel.Add(job, value);
			}
			if (value.ContainsKey(part))
			{
				return value[part];
			}
			int num = 0;
			for (int i = job * 10000 + part * 1000 + 1; Contain(i); i++)
			{
				num = Get(i).PowerLevel;
			}
			value.Add(part, num);
			return num;
		}

		public EquipPowerConfig GetEnhanceConfig(int job, int part, int level)
		{
			if (!_CachePowerLevelConfigs.TryGetValue(job, out var value))
			{
				value = new Dictionary<int, EquipPowerConfig>();
				_CachePowerLevelConfigs.Add(job, value);
			}
			int key = part * 10000 + level;
			if (value.ContainsKey(key))
			{
				return value[key];
			}
			int num = job * 10000 + part * 1000 + 1;
			int num2 = 0;
			while (Contain(num))
			{
				EquipPowerConfig equipPowerConfig = Get(num);
				if (equipPowerConfig.PowerLevel >= level)
				{
					for (int i = num2; i <= equipPowerConfig.PowerLevel; i++)
					{
						int key2 = part * 10000 + i;
						value.Add(key2, equipPowerConfig);
					}
					return equipPowerConfig;
				}
				num++;
				num2 = equipPowerConfig.PowerLevel + 1;
			}
			return null;
		}
	}
