			{
				return null;
			}
			return list[0];
		}

		public override void AfterEndInit()
		{
			FaBaoLevelList.Clear();
			foreach (FaBaoLevelConfig value in GetAll().Values)
			{
				if (!FaBaoLevelList.ContainsKey(value.FaBaoId))
				{
					FaBaoLevelList.Add(value.FaBaoId, new List<int> { 0 });
				}
				FaBaoLevelList[value.FaBaoId].Add(value.LevelUpValue);
			}
		}

		public void GetLevelStat(int FaBaoId, int Level, StatList statList)
		{
			if (Level < 0)
			{
				return;
			}
			int num = Level;
			if (!FaBaoLevelList.TryGetValue(FaBaoId, out var value) || value.Count <= 0)
			{
				return;
			}
			for (int i = 0; i < value.Count; i++)
			{
				int num2 = value[i];
				if (num2 <= Level)
				{
					num = Level - num2;
					num2 = ((i + 1 >= value.Count) ? GetMaxLevel(FaBaoId) : value[i + 1]);
					int multiple = Math.Min(num2 - value[i], num);
					FaBaoLevelConfig faBaoLevelConfig = Get(FaBaoId * 10000 + num2);
					statList.AddRange(faBaoLevelConfig.BaseStats, multiple);
				}
			}
		}

		public FaBaoLevelConfig GetLevelConfig(int FaBaoId, int Level)
		{
			if (Level <= 0)
			{
				return null;
			}
			if (GetMaxLevel(FaBaoId) < Level)
			{
				return null;
			}
			if (FaBaoLevelList.TryGetValue(FaBaoId, out var value))
			{
				if (value.Count <= 0)
				{
					return null;
				}
				for (int num = value.Count - 1; num >= 0; num--)
				{
					int num2 = value[num];
					if (num2 <= Level)
					{
						num2 = ((num + 1 >= value.Count) ? GetMaxLevel(FaBaoId) : value[num + 1]);
						num2 = Math.Min(num2, GetMaxLevel(FaBaoId));
						return Get(FaBaoId * 10000 + num2);
					}
				}
			}
			return null;
		}

		public int GetMaxLevel(int FaBaoId)
		{
			if (!FaBaoLevelList.ContainsKey(FaBaoId))
			{
				return -1;
			}
			return FaBaoLevelList[FaBaoId].Last();
		}
	}
