				SkillIdList.TryAdd(key, new List<(int, int)>());
				SkillIdList[key].Add((item2.Key, item2.Value));
			}
			foreach (List<(int, int)> value in SkillIdList.Values)
			{
				value.Sort(((int, int) a, (int, int) b) => a.Item1.CompareTo(b.Item1));
