				{
					LevelList.Add(value.FaBaoId, new List<int>());
				}
				LevelList[value.FaBaoId].Add(value.LevelUpValue);
			}
		}

		public void GetLevelStat(int FaBaoSoulConfigId, int Level, StatList statList)
		{
			if (Level < 0)
			{
				return;
			}
			if (!LevelList.TryGetValue(FaBaoSoulConfigId, out var value) || value.Count <= 0)
			{
				return;
			}
			statList.AddRange(Get(FaBaoSoulConfigId * 10000).BaseStats);
			for (int i = 0; i < value.Count; i++)
			{
				int num = value[i];
				if (num <= Level)
				{
					int num2 = ((i + 1 >= value.Count) ? GetMaxLevel(FaBaoSoulConfigId) : value[i + 1]);
					int multiple = Math.Min(num2 - num, Level - num);
					FaBaoSoulLevelConfig faBaoSoulLevelConfig = Get(FaBaoSoulConfigId * 10000 + num2);
					statList.AddRange(faBaoSoulLevelConfig.BaseStats, multiple);
					continue;
				}
				break;
			}
		}

		public FaBaoSoulLevelConfig Get(int FaBaoSoulConfigId, int Level)
		{
			if (Level < 0)
			{
				return null;
			}
			if (GetMaxLevel(FaBaoSoulConfigId) < Level)
			{
				return null;
			}
			if (LevelList.TryGetValue(FaBaoSoulConfigId, out var value))
			{
				if (value.Count <= 0)
				{
					return null;
				}
				for (int num = value.Count - 1; num >= 0; num--)
				{
					int num2 = value[num];
					if (num2 <= Level)
					{
						num2 = ((num + 1 >= value.Count) ? GetMaxLevel(FaBaoSoulConfigId) : value[num + 1]);
						num2 = Math.Min(num2, GetMaxLevel(FaBaoSoulConfigId));
						return Get(FaBaoSoulConfigId * 10000 + num2);
					}
				}
			}
			return null;
		}

		public int GetMaxLevel(int FaBaoId)
		{
			if (!LevelList.TryGetValue(FaBaoId, out var value))
			{
				return -1;
			}
			return value.Last();
		}
