	public class HeroTalentTemplateConfigCategory : ConfigSingleton<HeroTalentTemplateConfigCategory>, IMerge
	{
		[ProtoIgnore]
		[BsonIgnore]
		private Dictionary<int, HeroTalentTemplateConfig> dict = new Dictionary<int, HeroTalentTemplateConfig>();

		[BsonElement]
		[ProtoMember(1)]
		private List<HeroTalentTemplateConfig> list = new List<HeroTalentTemplateConfig>();

		[ProtoIgnore]
		[BsonIgnore]
		private Dictionary<int, List<HeroTalentTemplateConfig>> ConfigMap;

		public HeroTalentTemplateConfigCategory(List<HeroTalentTemplateConfig> list)
		{
			this.list = list;
		}

		public HeroTalentTemplateConfigCategory()
		{
		}

		public void Merge(object o)
		{
			HeroTalentTemplateConfigCategory heroTalentTemplateConfigCategory = o as HeroTalentTemplateConfigCategory;
			list.AddRange(heroTalentTemplateConfigCategory.list);
		}

		public void MergeAndInit(object o)
		{
			HeroTalentTemplateConfigCategory s = o as HeroTalentTemplateConfigCategory;
			List<HeroTalentTemplateConfig> list = s.list;
			if (list == null || list.Count <= 0)
			{
				return;
			}
			this.list = this.list.FindAll((HeroTalentTemplateConfig c) => !s.dict.ContainsKey(c.Id));
			foreach (HeroTalentTemplateConfig item in s.list)
			{
				dict[item.Id] = item;
				((ProtoObject)item).AfterEndInit();
			}
			((ProtoObject)this).AfterEndInit();
		}

		[ProtoAfterDeserialization]
		public void ProtoEndInit()
		{
			foreach (HeroTalentTemplateConfig item in list)
			{
				((ProtoObject)item).AfterEndInit();
				dict.Add(item.Id, item);
			}
			((ProtoObject)this).AfterEndInit();
		}

		public HeroTalentTemplateConfig Get(int id)
		{
			dict.TryGetValue(id, out var value);
			if (value == null)
			{
				Log.Info(string.Format("配置找不到，配置表名: {0}，配置id: {1}", "HeroTalentTemplateConfig", id));
			}
			return value;
		}

		public bool Contain(int id)
		{
			return dict.ContainsKey(id);
		}

		public Dictionary<int, HeroTalentTemplateConfig> GetAll()
		{
			return dict;
		}

		public List<HeroTalentTemplateConfig> GetList()
		{
			return list;
		}

		public HeroTalentTemplateConfig GetOne()
		{
			if (dict == null || dict.Count <= 0)
			{
				return null;
			}
			return list[0];
		}

		public List<HeroTalentTemplateConfig> GetByHeroId(int heroId)
		{
			if (ConfigMap == null)
			{
				ConfigMap = new Dictionary<int, List<HeroTalentTemplateConfig>>();
			}
			if (!ConfigMap.TryGetValue(heroId, out var value))
			{
				for (int i = heroId * 1000 + 1; Contain(i); i++)
				{
					if (value == null)
					{
						value = new List<HeroTalentTemplateConfig>();
					}
					value.Add(Get(i));
				}
				ConfigMap.TryAdd(heroId, value);
				return value;
			}
			return value;
		}
	}
