		public int GetAwardBySeasonAndSchedule(int season, int schedule)
		{
			LadderTopStageAwardsConfig seasonConfig = GetSeasonConfig(season);
			if (seasonConfig?.AwardDrop != null)
			{
				int num = 7 - schedule;
				if (num >= 0 && num < seasonConfig.AwardDrop.Length)
				{
					return seasonConfig.AwardDrop[num];
				}
			}
			return 0;
		}

		public LadderTopStageAwardsConfig GetSeasonConfig(int season)
		{
			LadderTopStageAwardsConfig ladderTopStageAwardsConfig = null;
			int num = int.MaxValue;
			foreach (LadderTopStageAwardsConfig item in list)
			{
				if (season >= item.SeasonStart && (item.SeasonEnd == 0 || season <= item.SeasonEnd))
				{
					int num2 = ((item.SeasonEnd == 0) ? int.MaxValue : (item.SeasonEnd - item.SeasonStart + 1));
					if (num2 < num)
					{
						num = num2;
						ladderTopStageAwardsConfig = item;
					}
				}
			}
			if (ladderTopStageAwardsConfig == null && season != 1)
			{
				return GetSeasonConfig(1);
			}
			return ladderTopStageAwardsConfig;
		}

		public int GetValidSeasonAward(int requestSeason, int schedule)
		{
			return GetAwardBySeasonAndSchedule(requestSeason, schedule);
		}

		public List<LadderTopRankAward> GetSeasonAwards(int season)
		{
			LadderTopStageAwardsConfig seasonConfig = GetSeasonConfig(season);
			if (seasonConfig?.AwardDrop == null)
			{
				return new List<LadderTopRankAward>();
			}
			if (!_configAwardsCache.TryGetValue(seasonConfig.Id, out var value))
			{
				value = seasonConfig.AwardDrop;
				_configAwardsCache[seasonConfig.Id] = value;
			}
			List<LadderTopRankAward> list = new List<LadderTopRankAward>(value.Length);
			int num = 7;
			while (num >= 1 && num - 1 < value.Length)
			{
				int num2 = 7 - num;
				list.Add(new LadderTopRankAward(season, num, value[num2]));
				num--;
			}
			return list;
		}
	}
