		public void InitConfigs(int activityId)
		{
			if (ActivityGiftConfigs.TryGetValue(activityId, out var _))
			{
				return;
			}
			Dictionary<int, TreasureHouseConfig> dictionary = new Dictionary<int, TreasureHouseConfig>();
			foreach (var (key, treasureHouseConfig2) in ConfigSingleton<TreasureHouseConfigCategory>.Instance.GetAll())
			{
				if (activityId == treasureHouseConfig2.ActId)
				{
					dictionary.Add(key, treasureHouseConfig2);
				}
			}
			ActivityGiftConfigs.Add(activityId, dictionary);
			ActivityIds.Add(activityId);
		}

		public Dictionary<int, TreasureHouseConfig> GetActivityGiftConfigs(int activityId)
		{
			if (!ActivityIds.Contains(activityId))
			{
				InitConfigs(activityId);
			}
			ActivityGiftConfigs.TryGetValue(activityId, out var value);
			return value;
		}
	}
