	[ChildOf(typeof(BeastModule))]
	[FriendOf(typeof(BeastModule))]
	[EnableMethod]
	public class Beast : Entity, IAwake, IAwake<int>, ISerializeToEntity, IDestroy
	{
		[BsonElement("Level")]
		public int _level;

		public int ConfigId { get; set; }

		public int Position { get; set; } = -1;

		public bool IsLock { get; set; }

		[BsonIgnore]
		public int Level
		{
			get
			{
				if (_level <= 0)
				{
					return 1;
				}
				return _level;
			}
			set
			{
				_level = value;
			}
		}

		[BsonIgnore]
		public bool IsMaxLevel
		{
			get
			{
				if (Type != 0)
				{
					return Level >= Config.MaxLevel;
				}
				return true;
			}
		}

		[BsonIgnore]
		public bool IsMaxGrade => Config.NextId == 0;

		[BsonIgnore]
		public int Type => Config.Type;

		[BsonIgnore]
		public int Grade => Config.Grade;

		[BsonIgnore]
		public int Quality => Config.Quality;

		[BsonIgnore]
		public int Star => Config.Star;

		[BsonIgnore]
		public string Name => Config.Name;

		[BsonIgnoreIfNull]
		[BsonDictionaryOptions(/*Could not decode attribute arguments.*/)]
		public Dictionary<int, int> Record { get; set; }

		[BsonIgnore]
		public BeastConfig Config => ConfigSingleton<BeastConfigCategory>.Instance.Get(ConfigId);

		[BsonIgnore]
		public BeastLevelConfig NextLevelConfig
		{
			get
			{
				if (IsMaxLevel)
				{
					return null;
				}
				List<BeastLevelConfig> levelConfigsByType = ConfigSingleton<BeastLevelConfigCategory>.Instance.GetLevelConfigsByType(Type);
				if (levelConfigsByType == null)
				{
					return null;
				}
				int nextLevel = Level + 1;
				return levelConfigsByType.FirstOrDefault((BeastLevelConfig config) => nextLevel <= config.LevelUpValue);
			}
		}

		[BsonIgnore]
		public string ModelAssetName => ConfigSingleton<ModelConfigCategory>.Instance.Get(Config.ModelId).AssetName;

		[BsonIgnore]
		public int ExpId => ConfigSingleton<BeastComposeConfigCategory>.Instance.Get(Config.Grade).ExpId;
	}
