	}
	public static class CharTypeHelper
	{
		public static CharType GetCharType(int charId)
		{
			if (charId < 1000)
			{
				if (charId <= 0)
				{
					return CharType.None;
				}
				return CharType.Role;
			}
			if (charId < 10000)
			{
				return CharType.Hero;
			}
			return CharType.Monster;
		}
	}
