	public struct NoticeParam
	{
		[StaticField]
		private static Regex typeRegex = new Regex("^@(?<type>[0-9]+)@");

		public NoticeParamType Type;

		public string Content;

		public NoticeParam(string message)
		{
			Match match = typeRegex.Match(message);
			if (!match.Success)
			{
				Type = NoticeParamType.Raw;
				Content = message;
			}
			else
			{
				Type = (NoticeParamType)int.Parse(match.Groups["type"].Value);
				Content = message.Remove(match.Index, match.Length);
			}
		}

		public override string ToString()
		{
			return $"@{(int)Type}@{Content}";
		}
	}
