	[ComponentOf(null)]
	public class DataBindComponent : Entity, IAwake, IDestroy
	{
		public struct DataBindItem
		{
			public int Priority;

			public Delegate Delegate;
		}

		[BsonIgnore]
		public Dictionary<string, Dictionary<int, DataBindItem>> FieldCallbacks = new Dictionary<string, Dictionary<int, DataBindItem>>();

		[BsonIgnore]
		public int Seed;
	}
	[FriendOf(typeof(DataBindComponent))]
	public static class DataBindComponentSystem
	{
		private class AwakeSystem : AwakeSystem<DataBindComponent>
		{
			protected override void Awake(DataBindComponent self)
			{
			}
		}

		private class DestroySystem : DestroySystem<DataBindComponent>
		{
			protected override void Destroy(DataBindComponent self)
			{
			}
		}

		private static int GenerateId(this DataBindComponent self)
		{
			return ++self.Seed;
		}

		private static void UnBind(this DataBindComponent self, string fieldName, int id)
		{
			if (self.FieldCallbacks.TryGetValue(fieldName, out var value))
			{
				value.Remove(id);
				if (value.Count == 0)
				{
					self.FieldCallbacks.Remove(fieldName);
				}
			}
		}

		public static void OnDataOnChange<T>(this DataBindComponent self, Action<T> setter, Func<T> getter, T value, string propertyName, bool ignoreEquals = false)
		{
			T val = getter();
			if (ignoreEquals || !EqualityComparer<T>.Default.Equals(val, value))
			{
				setter(value);
				self.Publish(propertyName, val, value);
			}
		}

		public static void OnDataOnChange<T>(this DataBindComponent self, ref T field, T value, string propertyName, bool ignoreEquals = false)
		{
			T val = field;
			if (ignoreEquals || !EqualityComparer<T>.Default.Equals(val, value))
			{
				field = value;
				self.Publish(propertyName, val, value);
			}
		}

		public static void UnBindAll(this DataBindComponent self)
		{
			self.FieldCallbacks.Clear();
		}

		public static void Publish<T>(this DataBindComponent self, string fieldName, T oldValue, T newValue)
		{
			if (!self.FieldCallbacks.TryGetValue(fieldName, out var value))
			{
				return;
			}
			List<DataBindComponent.DataBindItem> list = value.Values.ToList();
			list.Sort((DataBindComponent.DataBindItem a, DataBindComponent.DataBindItem b) => b.Priority - a.Priority);
			foreach (DataBindComponent.DataBindItem item in list)
			{
				if (item.Delegate is Action<T, T> action)
				{
					try
					{
						action(oldValue, newValue);
					}
					catch (Exception ex)
					{
						Log.Error(ex);
					}
				}
				else
				{
					Log.Error($"数据绑定发现不一致的数据类型 数据类型: {typeof(Action<T, T>)} 回调类型: {item.Delegate.GetType()}");
				}
			}
		}

		public static Action Bind<T>(this DataBindComponent self, string fieldName, Action<T, T> onChange, Func<T> firstValue = null, int priority = 0)
		{
			if (!self.FieldCallbacks.TryGetValue(fieldName, out var value))
			{
				value = new Dictionary<int, DataBindComponent.DataBindItem>();
				self.FieldCallbacks.Add(fieldName, value);
			}
			int id = self.GenerateId();
			value.Add(id, new DataBindComponent.DataBindItem
			{
				Priority = priority,
				Delegate = onChange
			});
			if (firstValue != null)
			{
				T val = firstValue();
				onChange?.Invoke(val, val);
			}
			return _UnBind;
			void _UnBind()
			{
				self.UnBind(fieldName, id);
			}
		}
	}
	[FriendOf(typeof(Entity))]
	public static class DataBindHelper
	{
		[EnableAccessEntiyChild]
		public static void DataChange<T>(this Entity self, ref T field, T value, bool ignoreEquals = false, [CallerMemberName] string propertyName = "")
		{
			DataBindComponent component = self.GetComponent<DataBindComponent>();
			if (component == null)
			{
				field = value;
			}
			else
			{
				component.OnDataOnChange(ref field, value, propertyName, ignoreEquals);
			}
		}

		[EnableAccessEntiyChild]
		public static void DataChange<T>(this Entity self, Action<T> setter, Func<T> getter, T value, bool ignoreEquals = false, [CallerMemberName] string propertyName = "")
		{
			DataBindComponent component = self.GetComponent<DataBindComponent>();
			if (component == null)
			{
				setter(value);
			}
			else
			{
				component.OnDataOnChange(setter, getter, value, propertyName, ignoreEquals);
			}
		}

		[EnableAccessEntiyChild]
		public static void DirectPublish<T>(this Entity self, string propertyName, Func<T> currentValue = null)
		{
			DataBindComponent component = self.GetComponent<DataBindComponent>();
			T val = default(T);
			if (currentValue != null)
			{
				val = currentValue();
			}
			component?.Publish(propertyName, val, val);
		}

		[EnableAccessEntiyChild]
		public static Action BindData<T>(this Entity self, string fieldName, Action<T, T> onChange, Func<T> firstValue = null, int priority = 0)
		{
			return self.GetComponent<DataBindComponent>()?.Bind(fieldName, onChange, firstValue, priority);
		}

		[EnableAccessEntiyChild]
		public static void EnableDataBind(this Entity self)
		{
			if (self.GetComponent<DataBindComponent>() == null)
			{
				self.AddComponent<DataBindComponent>(false);
			}
		}

		[EnableAccessEntiyChild]
		public static void BindDataWithAutoUnBind<T>(this Entity self, Entity dataOwner, string fieldName, Action<T, T> onChange, Func<T> firstValue = null, int priority = 0)
		{
			Action action = dataOwner.GetComponent<DataBindComponent>()?.Bind(fieldName, onChange, firstValue, priority);
			if (action != null)
			{
				AutoUnBindComponent obj = self.GetComponent<AutoUnBindComponent>() ?? self.AddComponent<AutoUnBindComponent>(false);
				obj.ClearAction = (Action)Delegate.Combine(obj.ClearAction, action);
			}
		}
	}
