	[ActivityConfigHandler(ActivityType.GemStonePlan)]
	public class GemStonePlanConfigHandler : AActivityConfigHandler<GemStonePlanBaseConfigCategory, GemStonePlanGiftConfigCategory, GemStonePlanTaskConfigCategory>
	{
		protected override (GemStonePlanBaseConfigCategory, GemStonePlanGiftConfigCategory, GemStonePlanTaskConfigCategory) GetConfigs(ActivityData data)
		{
			GemStonePlanBaseConfig gemStonePlanBaseConfig = ConfigSingleton<GemStonePlanBaseConfigCategory>.Instance.Get(data.ActivityId);
			List<GemStonePlanGiftConfig> list = new List<GemStonePlanGiftConfig>();
			int[] gemStonePlanGiftId = gemStonePlanBaseConfig.GemStonePlanGiftId;
			foreach (int id in gemStonePlanGiftId)
			{
				list.Add(ConfigSingleton<GemStonePlanGiftConfigCategory>.Instance.Get(id));
			}
			List<GemStonePlanTaskConfig> list2 = new List<GemStonePlanTaskConfig>();
			gemStonePlanGiftId = gemStonePlanBaseConfig.GemStonePlanObtainId;
			foreach (int id2 in gemStonePlanGiftId)
			{
				list2.Add(ConfigSingleton<GemStonePlanTaskConfigCategory>.Instance.Get(id2));
			}
			return (new GemStonePlanBaseConfigCategory(new List<GemStonePlanBaseConfig> { gemStonePlanBaseConfig }), new GemStonePlanGiftConfigCategory(list), new GemStonePlanTaskConfigCategory(list2));
		}
	}
