	public static class GuildHelper
	{
		public static void GetAllFlagIcon(ref List<GuildFlagConfig> flagList, ref List<GuildFlagConfig> iconList)
		{
			foreach (KeyValuePair<int, GuildFlagConfig> item in ConfigSingleton<GuildFlagConfigCategory>.Instance.GetAll())
			{
				if (item.Value.ShowType == 1)
				{
					flagList.Add(item.Value);
				}
				else
				{
					iconList.Add(item.Value);
				}
			}
		}

		public static string GetJobBg(int job)
		{
			return job switch
			{
				1 => "ui_xm_frame_44", 
				2 => "ui_xm_frame_45", 
				3 => "ui_xm_frame_46", 
				4 => "ui_xm_frame_51", 
				_ => string.Empty, 
			};
		}

		public static string GetPermissionName(int permission)
		{
			return permission switch
			{
				16 => "审批成员", 
				32 => "任命职位", 
				1 => "解散公会", 
				64 => "踢出成员", 
				4 => "修改公告", 
				2 => "仙盟改名", 
				8 => "修改旗帜", 
				128 => "转让盟主", 
				256 => "设置条件", 
				512 => "展示形象", 
				_ => string.Empty, 
			};
		}

		public static string GetName(Player player)
		{
			if (player == null)
			{
				return string.Empty;
			}
			GuildComponent component = ((Entity)SceneHelper.DomainScene((Entity)(object)player)).GetComponent<GuildComponent>();
			if (component == null)
			{
				return string.Empty;
			}
			component.PlayerGuildIdCache.TryGetValue(((Entity)player).Id, out var value);
			if (value == 0L)
			{
				return string.Empty;
			}
			return ((Entity)((Entity)SceneHelper.DomainScene((Entity)(object)player)).GetComponent<GuildComponent>()).GetChild<Guild>(value)?.Name ?? string.Empty;
		}

		public static long GetPower(this GuildModule self)
		{
			if (self.GuildInfo == null)
			{
				return 0L;
			}
			return self.GuildInfo.BaseInfo.Power;
		}

		public static GuildInfo GetInfo(this GuildModule self)
		{
			return ((Entity)((Entity)self).GetParent<Player>()).GetComponent<GuildModule>().GuildInfo;
		}

		public static string GetJobName(int job)
		{
			return ConfigSingleton<GuildJobConfigCategory>.Instance.Get(job)?.JobName ?? string.Empty;
		}

		public static (bool isMax, int lv, int pos) GetSkillLvByJob(this GuildModule self, int job)
		{
			int skillLv = self.GetSkillLv(job);
			int item = skillLv % 7;
			return (isMax: GetGuildSkillConfig(job, skillLv + 1) == null, lv: skillLv, pos: item);
		}

		public static int GetSkillLv(this GuildModule self, int job)
		{
			return self.SkillInfo?.GetValueOrDefault(job, 0) ?? 0;
		}

		public static int GetNextStageSkillLv(this GuildModule self, int job)
		{
			int num = self.GetSkillLv(job) % 7;
			return 7 - num;
		}

		public static string GetFlagAsset(int flag)
		{
			return ConfigSingleton<GuildFlagConfigCategory>.Instance.Get(flag).AssetsName;
		}

		public static string GetIconAsset(int icon)
		{
			return ConfigSingleton<GuildFlagConfigCategory>.Instance.Get(icon).AssetsName;
		}

		public static (bool IsMax, int Lv, int showExp, int nextExp) Exp2Lv(int exp)
		{
			Dictionary<int, GuildLevelConfig> all = ConfigSingleton<GuildLevelConfigCategory>.Instance.GetAll();
			GuildLevelConfig guildLevelConfig = null;
			int num = exp;
			int item = 0;
			foreach (KeyValuePair<int, GuildLevelConfig> item2 in all)
			{
				if (num >= item2.Value.Exp)
				{
					guildLevelConfig = item2.Value;
					num -= item2.Value.Exp;
					continue;
				}
				item = item2.Value.Exp;
				break;
			}
			return (IsMax: guildLevelConfig.Id == all.Last().Value.Id, Lv: guildLevelConfig.Id, showExp: num, nextExp: item);
		}

		public static int GetGuildLevel(long exp)
		{
			Dictionary<int, GuildLevelConfig> all = ConfigSingleton<GuildLevelConfigCategory>.Instance.GetAll();
			long num = exp;
			int result = 0;
			foreach (KeyValuePair<int, GuildLevelConfig> item in all)
			{
				if (num >= item.Value.Exp)
				{
					result = item.Value.Id;
					num -= item.Value.Exp;
					continue;
				}
				break;
			}
			return result;
		}

		public static int GetUnlockLevel(int job, int index)
		{
			index++;
			foreach (KeyValuePair<int, GuildLevelConfig> item in ConfigSingleton<GuildLevelConfigCategory>.Instance.GetAll())
			{
				switch (job)
				{
				case 2:
					if (item.Value.ViceLoaderCount == index)
					{
						return item.Value.Id;
					}
					break;
				case 3:
					if (item.Value.ElderCount == index)
					{
						return item.Value.Id;
					}
					break;
				}
			}
			return 1;
		}

		public static long GetJoinCDTime(this GuildModule self)
		{
			int guildLeaveCD = ConfigSingleton<GuildGlobalConfigCategory>.Instance.GetOne().GuildLeaveCD;
			long num = TimeHelper.ServerNow();
			long leaveTime = self.LeaveTime;
			return (long)guildLeaveCD * 1000L - (num - leaveTime);
		}

		public static List<GuildDonateConfig> GetDonateConfigs(this GuildModule self, int type)
		{
			List<GuildDonateConfig> list = new List<GuildDonateConfig>();
			int num = type * 1000;
			while (ConfigSingleton<GuildDonateConfigCategory>.Instance.Contain(num))
			{
				GuildDonateConfig item = ConfigSingleton<GuildDonateConfigCategory>.Instance.Get(num);
				num++;
				list.Add(item);
			}
			return list;
		}

		public static int ValidPermission(int job, GuildOperation operation)
		{
			GuildJobConfig guildJobConfig = ConfigSingleton<GuildJobConfigCategory>.Instance.Get(job);
			if (guildJobConfig == null)
			{
				return 202812;
			}
			bool flag = false;
			switch (operation)
			{
			case GuildOperation.Appoint:
				flag = guildJobConfig.Appoint;
				break;
			case GuildOperation.Disband:
				flag = guildJobConfig.Disband;
				break;
			case GuildOperation.Rename:
				flag = guildJobConfig.Rename;
				break;
			case GuildOperation.Notice:
				flag = guildJobConfig.Notice;
				break;
			case GuildOperation.Banner:
				flag = guildJobConfig.Banner;
				break;
			case GuildOperation.Approve:
				flag = guildJobConfig.Approve;
				break;
			case GuildOperation.Kick:
				flag = guildJobConfig.Kick;
				break;
			case GuildOperation.Transfer:
				flag = guildJobConfig.Transfer;
				break;
			case GuildOperation.Setting:
				flag = guildJobConfig.Setting;
				break;
			case GuildOperation.ShowModel:
				flag = guildJobConfig.ShowModel;
				break;
			}
			if (!flag)
			{
				return 202808;
			}
			return 0;
		}

		public static GuildSkillConfig GetGuildSkillConfig(int job, int lv)
		{
			return ConfigSingleton<GuildSkillConfigCategory>.Instance.Get(job * 100000 + lv);
		}

		public static List<Stat> GetGuildSkillStats(int job, int lv)
		{
			List<Stat> list = new List<Stat>();
			if (lv == 0)
			{
				Stat[] stats = GetGuildSkillConfig(job, lv + 1).Stats;
				foreach (Stat stat in stats)
				{
					list.Add(new Stat
					{
						Type = stat.Type,
						Value = 0L
					});
				}
			}
			else
			{
				Stat[] stats = GetGuildSkillConfig(job, lv).Stats;
				foreach (Stat stat2 in stats)
				{
					list.Add(new Stat
					{
						Type = stat2.Type,
						Value = stat2.Value
					});
				}
			}
			return list;
		}

