	[ChildOf(null)]
	public class Hero : Entity, IAwake<int>, IDestroy, ISerializeToEntity, IDeserialize
	{
		[BsonIgnore]
		private int _maxStar;

		[BsonIgnore]
		private int _totalTalentPoint;

		[BsonDictionaryOptions(/*Could not decode attribute arguments.*/)]
		public Dictionary<int, int> TalentData;

		[BsonDictionaryOptions(/*Could not decode attribute arguments.*/)]
		public Dictionary<int, int> Jewelrys { get; set; } = new Dictionary<int, int>();

		public int ConfigId { get; set; }

		[BsonIgnore]
		public Player Player => ((Entity)this).Parent.GetParent<Player>();

		[BsonIgnore]
		public HeroConfig Config => ConfigSingleton<HeroConfigCategory>.Instance.Get(ConfigId);

		[BsonIgnore]
		public HeroStarConfig StarConfig => ConfigSingleton<HeroStarConfigCategory>.Instance.Get(ConfigId * 100 + Star);

		[BsonIgnore]
		public HeroStarConfig NextStarConfig => ConfigSingleton<HeroStarConfigCategory>.Instance.Get(ConfigId * 100 + (Star + 1));

		[BsonIgnore]
		public HeroStarConfig LastStarConfig => ConfigSingleton<HeroStarConfigCategory>.Instance.Get(ConfigId * 100 + (Star - 1));

		public bool IsActive { get; set; }

		[BsonDictionaryOptions(/*Could not decode attribute arguments.*/)]
		public Dictionary<int, int> ActiveTalentNodes { get; set; }

		public int Star { get; set; }

		[BsonIgnore]
		public int MaxStar
		{
			get
			{
				if (_maxStar != 0)
				{
					return _maxStar;
				}
				_maxStar = Star;
				for (int i = ConfigId * 100 + Star + 1; ConfigSingleton<HeroStarConfigCategory>.Instance.Contain(i); i++)
				{
					_maxStar++;
				}
				return _maxStar;
			}
		}

		public bool IsMaxStar => Star >= MaxStar;

		public int TalentPoint { get; set; }

		[BsonIgnore]
		public int TotalTalentPoint
		{
			get
			{
				_totalTalentPoint = 0;
				int num = 0;
				int num2 = ConfigId * 100 + num;
				while (num <= Star)
				{
					HeroStarConfig heroStarConfig = ConfigSingleton<HeroStarConfigCategory>.Instance.Get(num2);
					_totalTalentPoint += heroStarConfig.AddTalentPoint;
					num++;
					num2++;
				}
				return _totalTalentPoint;
			}
		}

		public int ManualLv { get; set; }

		[BsonIgnore]
		public bool ManualCanLvUp
		{
			get
			{
				if (!IsActive)
				{
					return false;
				}
				if (!ManualIsActive)
				{
					return true;
				}
				return ManualLv < Star;
			}
		}

		public bool ManualIsActive { get; set; }

		public int CurrentSkin { get; set; }

		public int CurrentFaBao { get; set; }

		public List<int> FaBaoList { get; set; } = new List<int>();

		[BsonIgnore]
		public int CurrentSkinModelId
		{
			get
			{
				if (ConfigSingleton<HeroSkinConfigCategory>.Instance.Contain(CurrentSkin))
				{
					return ConfigSingleton<HeroSkinConfigCategory>.Instance.Get(CurrentSkin).ModelId;
				}
				return 0;
			}
		}

		[BsonIgnore]
		public Dictionary<int, HeroSkillData> SkillDataList { get; set; } = new Dictionary<int, HeroSkillData>();
	}
