	public class HeroRelateBuilder : IDisposable
	{
		private MultiMapSet<int, RelateInfo> HeroRelates = new MultiMapSet<int, RelateInfo>();

		private HashSet<RelateInfo> ActiveRelates = new HashSet<RelateInfo>();

		private HashSet<int> ActiveJobs = new HashSet<int>();

		public bool IsActiveJobRelate => ActiveJobs.Count == ConfigSingleton<JobConfigCategory>.Instance.GetAll().Count;

		public static HeroRelateBuilder Create()
		{
			return Singleton<ObjectPool>.Instance.Fetch<HeroRelateBuilder>();
		}

		public HeroRelateBuilder()
		{
			foreach (KeyValuePair<int, RelateConfig> item in ConfigSingleton<RelateConfigCategory>.Instance.GetAll())
			{
				item.Deconstruct(out var i, out var value);
				int relateId = i;
				RelateConfig relateConfig = value;
				RelateInfo relateInfo = new RelateInfo
				{
					RelateId = relateId,
					ActiveHeroes = new Dictionary<int, int>()
				};
				int[] heros = relateConfig.Heros;
				for (i = 0; i < heros.Length; i++)
				{
					int num = heros[i];
					HeroRelates.Add(num, relateInfo);
				}
			}
		}

		public void Dispose()
		{
			Clear();
			Singleton<ObjectPool>.Instance.Recycle((object)this);
		}

		public void Clear()
		{
			foreach (KeyValuePair<int, HashSet<RelateInfo>> item in (SortedDictionary<int, HashSet<RelateInfo>>)(object)HeroRelates)
			{
				foreach (RelateInfo item2 in item.Value)
				{
					item2.ActiveHeroes.Clear();
					item2.Star = 0;
					item2.IsActive = false;
				}
			}
			ActiveRelates.Clear();
			ActiveJobs.Clear();
		}

		public void SetHeroStar(int heroId, int star)
		{
			HeroConfig heroConfig = ConfigSingleton<HeroConfigCategory>.Instance.Get(heroId);
			if (ConfigSingleton<JobConfigCategory>.Instance.Contain(heroConfig.Job))
			{
				ActiveJobs.Add(heroConfig.Job);
			}
			if (!((SortedDictionary<int, HashSet<RelateInfo>>)(object)HeroRelates).TryGetValue(heroId, out HashSet<RelateInfo> value))
			{
				return;
			}
			foreach (RelateInfo item in value)
			{
				item.ActiveHeroes[heroId] = star;
				RelateConfig config = item.Config;
				if (config.Heros.Length != item.ActiveHeroes.Count)
				{
					continue;
				}
				item.IsActive = true;
				ActiveRelates.Add(item);
				int num = int.MaxValue;
				int[] heros = config.Heros;
				foreach (int key in heros)
				{
					num = math.min(item.ActiveHeroes[key], num);
					if (num == 0)
					{
						break;
					}
				}
				int num2 = item.RelateId * 100;
				while (ConfigSingleton<RelateStarConfigCategory>.Instance.Contain(++num2))
				{
					RelateStarConfig relateStarConfig = ConfigSingleton<RelateStarConfigCategory>.Instance.Get(num2);
					if (num >= relateStarConfig.NeedStar)
					{
						item.Star = relateStarConfig.RelateStar;
					}
					else if (num < relateStarConfig.NeedStar)
					{
						break;
					}
				}
			}
		}

		public HashSet<RelateInfo> GetHeroRelate(int heroConfigId)
		{
			return ((IReadOnlyDictionary<int, HashSet<RelateInfo>>)HeroRelates).GetValueOrDefault(heroConfigId);
		}

		public IEnumerable<RelateInfo> GetActiveRelates()
		{
			return ActiveRelates;
		}

		public IEnumerable<int> GetActiveJobs()
		{
			return ActiveJobs;
		}
	}
