	public class Item : Entity, IAwake<int>, IDestroy, ISerializeToEntity
	{
		[BsonIgnore]
		public Player Owner => ((Entity)this).Parent.GetParent<Player>();

		public int ConfigId { get; set; }

		[BsonIgnore]
		public ItemConfig Config => ConfigSingleton<ItemConfigCategory>.Instance.GetFromAll(ConfigId);

		[BsonIgnore]
		public ItemTapType TapType => (ItemTapType)Config.TabType;

		public long Nums { get; set; }

		[BsonIgnoreIfDefault]
		public long ExpiredTime { get; set; }

		[BsonIgnore]
		public int TakeSlot
		{
			get
			{
				int num = math.max(Config.MaxStacked, 1);
				return (int)((Nums + num - 1) / num);
			}
		}

		[BsonIgnore]
		public bool Read { get; set; }

		[BsonIgnore]
		public bool Red
		{
			get
			{
				if (Config.Type == 6 || Config.Type == 7)
				{
					return true;
				}
				if (Config.IsComposable)
				{
					return Nums >= Config.ComposeCost;
				}
				return !Read;
			}
		}
	}
