	public class ItemList : IDisposable, IEnumerable<ItemStruct>, IEnumerable
	{
		private List<ItemStruct> list = new List<ItemStruct>();

		private Dictionary<int, int> indexMap = new Dictionary<int, int>();

		private bool Merge = true;

		public int Count => list.Count;

		public ItemStruct this[int index] => list[index];

		public void SetNums(int configId, long nums)
		{
			if (indexMap.TryGetValue(configId, out var value))
			{
				ItemStruct value2 = list[value];
				value2.Nums = nums;
				list[value] = value2;
			}
		}

		public long GetNums(int configId)
		{
			if (indexMap.TryGetValue(configId, out var value))
			{
				return list[value].Nums;
			}
			return 0L;
		}

		public void Sort(Comparison<ItemStruct> comparison)
		{
			list.Sort(comparison);
			if (Merge)
			{
				indexMap.Clear();
				for (int i = 0; i < list.Count; i++)
				{
					ItemStruct itemStruct = list[i];
					indexMap.Add(itemStruct.ConfigId, i);
				}
			}
		}

		public static ItemList Create(bool merge = true)
		{
			ItemList itemList = Singleton<ObjectPool>.Instance.Fetch<ItemList>();
			itemList.Merge = merge;
			return itemList;
		}

		public void Clear()
		{
			list.Clear();
			indexMap.Clear();
		}

		public void Clean()
		{
			indexMap.Clear();
			for (int i = 0; i < list.Count; i++)
			{
				ItemStruct itemStruct = list[i];
				if (itemStruct.Nums <= 0)
				{
					list.RemoveAt(i);
					i--;
				}
				else
				{
					indexMap.Add(itemStruct.ConfigId, i);
				}
			}
		}

		public void Add(ItemStruct item)
		{
			int value;
			if (!Merge)
			{
				list.Add(item);
			}
			else if (!indexMap.TryGetValue(item.ConfigId, out value))
			{
				indexMap[item.ConfigId] = list.Count;
				list.Add(item);
			}
			else
			{
				ItemStruct value2 = list[value];
				value2.Nums += item.Nums;
				list[value] = value2;
			}
		}

		public void Add(ET.ConfigBeans.Item item)
		{
			Add(new ItemStruct
			{
				ConfigId = item.Id,
				Nums = item.Nums
			});
		}

		public void Add(ET.ConfigBeans.Item item, long multi)
		{
			Add(new ItemStruct
			{
				ConfigId = item.Id,
				Nums = item.Nums * multi
			});
		}

		public void AddRange(List<Item> items)
		{
			if (items == null || items.Count <= 0)
			{
				return;
			}
			foreach (Item item in items)
			{
				Add(new ItemStruct
				{
					ConfigId = item.ConfigId,
					Nums = (int)item.Nums
				});
			}
		}

		public void AddRange(ET.ConfigBeans.Item[] items)
		{
			if (items != null && items.Length != 0)
			{
				foreach (ET.ConfigBeans.Item item in items)
				{
					Add(new ItemStruct
					{
						ConfigId = item.Id,
						Nums = item.Nums
					});
				}
			}
		}

		public void AddRange(ET.ConfigBeans.Item[] items, int multi)
		{
			if (items != null && items.Length != 0)
			{
				foreach (ET.ConfigBeans.Item item in items)
				{
					Add(new ItemStruct
					{
						ConfigId = item.Id,
						Nums = item.Nums * multi
					});
				}
			}
		}

		public void AddRange(DropItem[] items)
		{
			if (items != null && items.Length != 0)
			{
				foreach (DropItem dropItem in items)
				{
					Add(new ItemStruct
					{
						ConfigId = dropItem.Id,
						Nums = dropItem.Nums
					});
				}
			}
		}

		public void AddRange(IEnumerable<ItemStruct> itemList)
		{
			if (itemList == null)
			{
				return;
			}
			foreach (ItemStruct item in itemList)
			{
				Add(item);
			}
		}

		public void Dispose()
		{
			list.Clear();
			indexMap.Clear();
			Singleton<ObjectPool>.Instance.Recycle((object)this);
		}

		public IEnumerator<ItemStruct> GetEnumerator()
		{
			return list.GetEnumerator();
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return GetEnumerator();
		}

		public void SetMulti(int multi)
		{
			for (int i = 0; i < list.Count; i++)
			{
				ItemStruct value = list[i];
				value.Nums *= multi;
				list[i] = value;
			}
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			foreach (ItemStruct item in list)
			{
				stringBuilder.AppendLine($"{item.ConfigId}: {item.Nums}");
			}
			return stringBuilder.ToString();
		}
	}
