	public class ItemModuleAwakeSystem : AwakeSystem<ItemModule>
	{
		protected override void Awake(ItemModule self)
		{
			self.UsedPropSlotNums = 0;
			self.UsedEquipSlotNums = 0;
			self.UsedHeroSlotNums = 0;
			foreach (Item value in ((Entity)self).Children.Values)
			{
				switch (value.TapType)
				{
				case ItemTapType.Equip:
					self.UsedEquipSlotNums += value.TakeSlot;
					break;
				case ItemTapType.Hero:
					self.UsedHeroSlotNums += value.TakeSlot;
					break;
				default:
					self.UsedPropSlotNums += value.TakeSlot;
					break;
				}
			}
		}
	}
