	public class PowerCalc : IDisposable
	{
		private bool isDirty;

		private long power;

		private StatList statList;

		private SkillList skillList;

		public long Power => CalcInterval();

		public static PowerCalc Create()
		{
			PowerCalc powerCalc = Singleton<ObjectPool>.Instance.Fetch<PowerCalc>();
			powerCalc.statList = StatList.Create();
			powerCalc.skillList = SkillList.Create();
			powerCalc.isDirty = false;
			powerCalc.power = 0L;
			return powerCalc;
		}

		private long CalcInterval()
		{
			if (!isDirty)
			{
				return power;
			}
			isDirty = true;
			power = 0L;
			foreach (int skill in skillList)
			{
				if (new SkillLevel(skill).IsActiveSkill)
				{
					power += ConfigSingleton<ActiveSkillLevelConfigCategory>.Instance.Get(skill)?.Power ?? 0;
				}
				else
				{
					power += ConfigSingleton<PassiveSkillLevelConfigCategory>.Instance.Get(skill)?.Power ?? 0;
				}
			}
			foreach (StatStruct stat in statList)
			{
				int num = stat.Type % 100;
				if (num == stat.Type)
				{
					int type = num + 100;
					long value = statList.GetValue(num);
					long value2 = statList.GetValue(type);
					long num2 = value + value * value2 / 10000;
					power += num2 * ConfigSingleton<StatConfigCategory>.Instance.Get(num).PowerFactor / 100;
				}
			}
			return power;
		}

		public void AddSkill(int skillLevelId)
		{
			skillList.Add(skillLevelId);
			isDirty = true;
		}

		public void AddStat(Stat stat)
		{
			StatStruct stat2 = new StatStruct
			{
				Type = stat.Type,
				Value = stat.Value
			};
			statList.Add(stat2);
			isDirty = true;
		}

		public void AddStats(Stat[] stats)
		{
			if (stats != null && stats.Length > 0)
			{
				foreach (Stat stat in stats)
				{
					AddStat(stat);
				}
			}
		}

		public void AddStat(StatStruct stat)
		{
			StatStruct stat2 = stat;
			stat2.Scope = 0;
			statList.Add(stat2);
			isDirty = true;
		}

		public void AddStats(StatList statList)
		{
			if (statList == null || statList.Count <= 0)
			{
				return;
			}
			foreach (StatStruct stat in statList)
			{
				AddStat(stat);
			}
		}

		public void AddSkills(IEnumerable<int> skillLevelIds)
		{
			skillList.AddRange(skillLevelIds);
			isDirty = true;
		}

		public void Dispose()
		{
			statList.Dispose();
			statList = null;
			skillList.Dispose();
			skillList = null;
			Singleton<ObjectPool>.Instance.Recycle((object)this);
		}
	}
