		[BsonIgnoreIfDefault]
		public int PostId { get; set; }

		[BsonIgnore]
		public Player Player => ((Entity)((Entity)this).GetParent<RiverMapModule>()).GetParent<Player>();

		[BsonIgnore]
		public long ExpireTime => (long)ConfigSingleton<RiverMapGlobalConfigCategory>.Instance.GetOne().NormalEventTime * 1000L - (TimeHelper.Now() - CreateTime);

		[BsonIgnore]
		public int EventType => Config.EventType;

		[BsonIgnore]
		public int Quality => Config.Quality;

		[BsonIgnore]
		public RiverMapEventConfig Config => ConfigSingleton<RiverMapEventConfigCategory>.Instance.Get(ConfigId);

		[BsonIgnore]
		public bool IsExpired
		{
			get
			{
				if (MainType == 1)
				{
					return TimeHelper.Now() + 2000 >= CreateTime + (long)ConfigSingleton<RiverMapGlobalConfigCategory>.Instance.GetOne().NormalEventTime * 1000L;
				}
				return false;
			}
		}

		[BsonIgnore]
		public int PositionX { get; set; }

		[BsonIgnore]
		public int PositionY { get; set; }
	}
