	[PlayerModule(Offline = true)]
	[ComponentOf(typeof(Player))]
	public class RoleInfoModule : Entity, IAwake, IDeserialize
	{
		public byte Sex;

		public long LastLoginTime;

		public int LoginDays;

		public int ConsecutiveLoginDays;

		[BsonElement("Power")]
		private long _power;

		[BsonIgnore]
		public Player Player => ((Entity)this).GetParent<Player>();

		public string Account { get; set; }

		public string Name { get; set; }

		public int Zone { get; set; }

		[BsonIgnore]
		public string Name_C
		{
			get
			{
				return Name;
			}
			set
			{
				((Entity)(object)this).DataChange(delegate(string x)
				{
					Name = x;
				}, () => Name, value, ignoreEquals: false, "Name_C");
			}
		}

		public int Role { get; set; }

		[BsonIgnore]
		public int Role_C
		{
			get
			{
				return Role;
			}
			set
			{
				((Entity)(object)this).DataChange(delegate(int x)
				{
					Role = x;
				}, () => Role, value, ignoreEquals: false, "Role_C");
			}
		}

		public long CreateTime { get; set; }

		[BsonIgnore]
		public byte Sex_C
		{
			get
			{
				return Sex;
			}
			set
			{
				((Entity)(object)this).DataChange(ref Sex, value, ignoreEquals: false, "Sex_C");
			}
		}

		public bool IsNewbieMail { get; set; }

		[BsonIgnore]
		public long OnlineTime { get; set; }

		public long OfflineTime { get; set; }

		[BsonIgnore]
		public bool ShowVip { get; set; }

		public bool IsShowVip { get; set; } = true;

		[BsonIgnore]
		public bool ShowVip_C
		{
			get
			{
				return IsShowVip;
			}
			set
			{
				((Entity)(object)this).DataChange(delegate(bool x)
				{
					IsShowVip = x;
				}, () => IsShowVip, value, ignoreEquals: false, "ShowVip_C");
			}
		}

		[BsonIgnore]
		public int LoginDays_C
		{
			get
			{
				return LoginDays;
			}
			set
			{
				((Entity)(object)this).DataChange(ref LoginDays, value, ignoreEquals: false, "LoginDays_C");
			}
		}

		[BsonIgnore]
		public int ConsecutiveLoginDays_C
		{
			get
			{
				return ConsecutiveLoginDays;
			}
			set
			{
				((Entity)(object)this).DataChange(ref ConsecutiveLoginDays, value, ignoreEquals: false, "ConsecutiveLoginDays_C");
			}
		}

		[BsonIgnore]
		public long Power
		{
			get
			{
				return _power;
			}
			set
			{
				if (value != _power)
				{
					long power = _power;
					_power = value;
					Singleton<EventSystem>.Instance.Publish<ChangePower>(SceneHelper.DomainScene((Entity)(object)this), new ChangePower
					{
						Player = Player,
						Power = _power,
						Old = power
					});
				}
			}
		}

		[BsonIgnore]
		public long ServerOpenTime { get; set; }

		[BsonIgnore]
		public int ServerOpenDays
		{
			get
			{
				if (ServerOpenTime <= 0)
				{
					return 0;
				}
				long num = TimeHelper.Now();
				if (num < ServerOpenTime)
				{
					return 0;
				}
				return TimeHelper.DaysBetween(num, ServerOpenTime, 18000000L);
			}
		}

		[BsonIgnore]
		public long ServerMergeTime { get; set; }

		[BsonIgnore]
		public int ServerMergeDays
		{
			get
			{
				if (ServerMergeTime <= 0)
				{
					return 0;
				}
				long num = TimeHelper.Now();
				if (num < ServerMergeTime)
				{
					return 0;
				}
				return TimeHelper.DaysBetween(num, ServerMergeTime, 18000000L);
			}
		}
	}
