	public class SkillList : IDisposable, IEnumerable<int>, IEnumerable
	{
		private Dictionary<int, int> skillLevelMap = new Dictionary<int, int>();

		public int Count => skillLevelMap.Count;

		public static SkillList Create()
		{
			return Singleton<ObjectPool>.Instance.Fetch<SkillList>();
		}

		public void AddRange(IEnumerable<int> skillLevelIds)
		{
			if (skillLevelIds == null)
			{
				return;
			}
			foreach (int skillLevelId in skillLevelIds)
			{
				Add(skillLevelId);
			}
		}

		public int GetSkillLevelId(int skillLevelId)
		{
			SkillLevel skillLevel = new SkillLevel(skillLevelId);
			if (skillLevelMap.TryGetValue(skillLevel.SkillId, out var value))
			{
				return value;
			}
			return 0;
		}

		public void Add(int skillLevelId)
		{
			if (skillLevelId > 0)
			{
				SkillLevel skillLevel = new SkillLevel(skillLevelId);
				if (!skillLevelMap.TryGetValue(skillLevel.SkillId, out var value) || value < skillLevelId)
				{
					skillLevelMap[skillLevel.SkillId] = skillLevelId;
				}
			}
		}

		public void Dispose()
		{
			skillLevelMap.Clear();
			Singleton<ObjectPool>.Instance.Recycle((object)this);
		}

		public IEnumerator<int> GetEnumerator()
		{
			return skillLevelMap.Values.GetEnumerator();
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return GetEnumerator();
		}

		public List<int> ToList()
		{
			return new List<int>(skillLevelMap.Values);
		}
	}
