		protected abstract void UpdateJob(Player player, StatList updateList, int job);

		protected abstract void UpdateTeam(Player player, StatList updateList);

		public void UpdateScope(Player player, StatList updateList, int scope)
		{
			switch (scope)
			{
			case 1:
			case 2:
			case 3:
				UpdateJob(player, updateList, scope);
