	public class StatList : IDisposable, IEnumerable<StatStruct>, IEnumerable
	{
		private List<StatStruct> list = new List<StatStruct>();

		private Dictionary<int, int> indexMap = new Dictionary<int, int>();

		public int Count => list.Count;

		public StatStruct this[int index] => list[index];

		public static StatList Create()
		{
			return Singleton<ObjectPool>.Instance.Fetch<StatList>();
		}

		public void Clear()
		{
			list.Clear();
			indexMap.Clear();
		}

		public void Add(StatStruct stat)
		{
			int key = stat.Scope * 1000 + stat.Type;
			if (!indexMap.TryGetValue(key, out var value))
			{
				indexMap[key] = list.Count;
				list.Add(stat);
			}
			else
			{
				StatStruct value2 = list[value];
				value2.Value += stat.Value;
				list[value] = value2;
			}
		}

		public bool isExist(int type)
		{
			return indexMap.ContainsKey(type);
		}

		public long GetValue(int type)
		{
			if (indexMap.TryGetValue(type, out var value))
			{
				return list[value].Value;
			}
			return 0L;
		}

		public long GetValue(int type, int scope)
		{
			int key = scope * 1000 + type;
			if (indexMap.TryGetValue(key, out var value))
			{
				return list[value].Value;
			}
			return 0L;
		}

		public void AddRange(IEnumerable<Stat> iEnumerator, int multiple = 1)
		{
			if (iEnumerator == null)
			{
				return;
			}
			foreach (Stat item in iEnumerator)
			{
				Add(new StatStruct
				{
					Type = item.Type,
					Value = item.Value * multiple,
					Scope = item.Scope
				});
			}
		}

		public void AddRange(IEnumerable<StatStruct> iEnumerator, int multiple = 1)
		{
			if (iEnumerator == null)
			{
				return;
			}
			foreach (StatStruct item in iEnumerator)
			{
				Add(new StatStruct
				{
					Type = item.Type,
					Value = item.Value * multiple,
					Scope = item.Scope
				});
			}
		}

		public StatList GetRange(int index, int count)
		{
			StatList statList = new StatList();
			statList.AddRange(list.GetRange(index, count));
			return statList;
		}

		public void ReduceRange(IEnumerable<Stat> iEnumerator, int multiple = 1)
		{
			if (iEnumerator == null)
			{
				return;
			}
			foreach (Stat item in iEnumerator)
			{
				Add(new StatStruct
				{
					Type = item.Type,
					Value = -item.Value * multiple,
					Scope = item.Scope
				});
			}
		}

		public void Dispose()
		{
			list.Clear();
			indexMap.Clear();
			Singleton<ObjectPool>.Instance.Recycle((object)this);
		}

		public IEnumerator<StatStruct> GetEnumerator()
		{
			return list.GetEnumerator();
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return GetEnumerator();
		}
	}
