	public static class OpcodeHelper
	{
		[StaticField]
		private static readonly HashSet<ushort> ignoreDebugLogMessageSet = new HashSet<ushort>
		{
			20001,
			10018,
			10019,
			10033,
			10034,
			10731,
			10732,
			10733,
			11116,
			ushort.MaxValue
		};

		private static bool IsNeedLogMessage(ushort opcode)
		{
			if (ignoreDebugLogMessageSet.Contains(opcode))
			{
				return false;
			}
			return true;
		}

		public static bool IsOuterMessage(ushort opcode)
		{
			return opcode < 20000;
		}

		public static bool IsInnerMessage(ushort opcode)
		{
			return opcode >= 20001;
		}

		public static void LogMsg(int zone, object message)
		{
			if (IsNeedLogMessage(Singleton<NetServices>.Instance.GetOpcode(message.GetType())))
			{
				Singleton<Logger>.Instance.Debug("zone: {0} {1}", new object[2] { zone, message });
			}
		}

		public static void LogMsg(long actorId, object message)
		{
			if (IsNeedLogMessage(Singleton<NetServices>.Instance.GetOpcode(message.GetType())))
			{
				Singleton<Logger>.Instance.Debug("actorId: {0} {1}", new object[2] { actorId, message });
			}
		}
	}
