		{
			self[nt] = value;
		}

		public static void Set(this NumericComponent self, NumericType nt, long value)
		{
			self[nt] = value;
		}

		public static void SetNoEvent(this NumericComponent self, NumericType numericType, long value)
		{
			self.Insert(numericType, value, isPublishEvent: false);
		}

		public static void Insert(this NumericComponent self, NumericType numericType, long value, bool isPublishEvent = true)
		{
			long byKey = self.GetByKey(numericType);
			if (byKey != value)
			{
				self.NumericDic[numericType] = value;
				if ((int)numericType < 900)
				{
					self.Update(numericType, isPublishEvent);
				}
				if (isPublishEvent)
				{
					Singleton<EventSystem>.Instance.Publish<NumbericChange>(SceneHelper.DomainScene((Entity)(object)self), new NumbericChange
					{
						Unit = ((Entity)self).GetParent<Unit>(),
						New = value,
						Old = byKey,
						NumericType = numericType
					});
				}
			}
		}

		public static long GetByKey(this NumericComponent self, NumericType key)
		{
			long value = 0L;
			self.NumericDic.TryGetValue(key, out value);
			return value;
		}

		public static void Update(this NumericComponent self, NumericType numericType, bool isPublishEvent)
		{
			int num = (int)numericType % 100;
			int num2 = num + 100;
			int num3 = num + 200;
			int num4 = num + 300;
			int num5 = num + 900;
			long num6 = self[(NumericType)num];
			long num7 = self[(NumericType)num2];
			long num8 = self[(NumericType)num3];
			long num9 = self[(NumericType)num4];
			long num10 = num6 + num6 * num7 / 10000 + num8;
			num10 += num10 * num9 / 10000;
			self.Insert((NumericType)num5, num10, isPublishEvent);
		}
	}
