	public static class TimeHelper
	{
		public const long OneWeek = 604800000L;

		public const long OneDay = 86400000L;

		public const long Hour = 3600000L;

		public const long Minute = 60000L;

		public const long ResetTimePoint_Default = 18000000L;

		public const long ResetTimePoint_Zero = 0L;

		public static string FormatTimeWeek(DateTime time)
		{
			int num = (int)((time.DayOfWeek == DayOfWeek.Sunday) ? ((DayOfWeek)7) : time.DayOfWeek);
			return "星期" + ((StringHelper.NumToCN(num) == "七") ? "日" : StringHelper.NumToCN(num));
		}

		public static long ClientNow()
		{
			return Singleton<TimeInfo>.Instance.ClientNow();
		}

		public static long ClientNowSeconds()
		{
			return ClientNow() / 1000;
		}

		public static long ServerNow()
		{
			return Singleton<TimeInfo>.Instance.ServerNow();
