		{
			return Singleton<TimeInfo>.Instance.ClientFrameTime();
		}

		public static long ServerFrameTime()
		{
			return Singleton<TimeInfo>.Instance.ServerFrameTime();
		}

		public static int TimeZone()
		{
			return Singleton<TimeInfo>.Instance.TimeZone;
		}

		public static DateTime ToDateTime(long time)
		{
			return Singleton<TimeInfo>.Instance.ToDateTime(time);
		}

		public static DateTime DateTimeNow()
		{
			return Singleton<TimeInfo>.Instance.ToDateTime(ServerNow());
		}

		public static long Now()
		{
			return ServerNow();
		}

		public static long ToTime(int year, int month, int day, int hour = 0, int minute = 0, int second = 0)
		{
			DateTime dateTime = new DateTime(year, month, day, hour, minute, second, DateTimeKind.Utc).AddHours(-TimeZone());
			DateTime dateTime2 = new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc);
			return (long)(dateTime - dateTime2).TotalMilliseconds;
		}

		public static long ToTime(DateTime timeData)
		{
			return ToTime(timeData.Year, timeData.Month, timeData.Day, timeData.Hour, timeData.Minute, timeData.Second);
		}

		public static int DaysBetween(long time1, long time2, long resetTimePoint = 18000000L)
		{
			long num = (long)TimeZone() * 3600000L - resetTimePoint;
			time1 += num;
			time2 += num;
			return (int)math.abs(time1 / 86400000 - time2 / 86400000) + 1;
		}

		public static bool IsSameDay(long time1, long time2, long resetTimePoint = 18000000L)
		{
			if (math.abs(time1 - time2) > 86400000)
			{
				return false;
			}
			long num = (long)TimeZone() * 3600000L - resetTimePoint;
			time1 += num;
			time2 += num;
			return time1 / 86400000 == time2 / 86400000;
		}

		public static long BeginTimeOfDay(long time, long resetTimePoint = 18000000L)
		{
			return EndTimeOfDay(time - 86400000, resetTimePoint);
		}

		public static long EndTimeOfDay(long time, long resetTimePoint = 18000000L)
		{
			long num = (long)TimeZone() * 3600000L - resetTimePoint;
			long num2 = (time + num) % 86400000;
			return time + 86400000 - num2;
		}

		public static long CommonEndTimeOfDay(long time)
		{
			return EndTimeOfDay(time, 18000000L) - ConfigSingleton<GlobalConfigCategory>.Instance.GetOne().CommonSettleTime * 1000;
		}

		public static long GetDurationToEndDay(long now, long resetTimePoint = 18000000L)
		{
			return EndTimeOfDay(now, resetTimePoint) - now;
		}

		public static int GetDayInWeek(long time, long resetTimePoint = 18000000L)
		{
			time -= resetTimePoint;
			DateTime dateTime = ToDateTime(time);
			if (dateTime.DayOfWeek != DayOfWeek.Sunday)
			{
				return (int)dateTime.DayOfWeek;
			}
			return 7;
		}

		public static int WeeksBetween(long time1, long time2, long resetTimePoint = 18000000L)
		{
			long num = (long)TimeZone() * 3600000L - resetTimePoint;
			time1 += num;
			time2 += num;
			return (int)math.abs(time1 / 604800000 - time2 / 604800000) + 1;
		}

		public static int NaturalWeeksBetween(long time1, long time2, long resetTimePoint = 18000000L)
		{
			long num = (long)TimeZone() * 3600000L - resetTimePoint;
			time1 += num;
			time2 += num;
			long num2 = time1 / 86400000 + 3;
			long num3 = time2 / 86400000 + 3;
			long num4 = num2 / 7;
			long num5 = num3 / 7;
			return (int)math.abs(num4 - num5);
		}

		public static bool IsSameWeek(long time1, long time2, long resetTimePoint = 18000000L)
		{
			if (math.abs(time1 - time2) > 604800000)
			{
				return false;
			}
			long num = (long)TimeZone() * 3600000L - resetTimePoint;
			time1 += num;
			time2 += num;
			long num2 = time1 / 86400000 + 3;
			long num3 = time2 / 86400000 + 3;
			return num2 / 7 == num3 / 7;
		}

		public static long BeginTimeOfWeek(long now, long resetTimePoint = 18000000L)
		{
			int dayInWeek = GetDayInWeek(now, resetTimePoint);
			now -= (long)(dayInWeek - 1) * 86400000L;
			return BeginTimeOfDay(now, resetTimePoint);
		}

		public static long EndTimeOfWeek(long now, long resetTimePoint = 18000000L)
		{
			return BeginTimeOfWeek(now, resetTimePoint) + 604800000;
		}

		public static long GetDurationToEndWeek(long now, long resetTimePoint = 18000000L)
		{
			return EndTimeOfWeek(now, resetTimePoint) - now;
		}

		public static int GetDayInMonth(long time)
		{
			return ToDateTime(time).Day;
		}

		public static int GetTotalDaysInMonth(long time)
		{
			DateTime dateTime = ToDateTime(time);
			return DateTime.DaysInMonth(dateTime.Year, dateTime.Month);
		}

		public static bool IsSameMonth(long time1, long time2, long resetTimePoint = 18000000L)
		{
			time1 -= resetTimePoint;
			time2 -= resetTimePoint;
			DateTime dateTime = ToDateTime(time1);
			DateTime dateTime2 = ToDateTime(time2);
			if (dateTime.Month == dateTime2.Month)
			{
				return dateTime.Year == dateTime2.Year;
			}
			return false;
		}

		public static long BeginTimeOfMonth(long now, long resetTimePoint = 18000000L)
		{
			int dayInMonth = GetDayInMonth(now);
			now -= (long)(dayInMonth - 1) * 86400000L;
			return BeginTimeOfDay(now, resetTimePoint);
		}

		public static long EndTimeOfMonth(long now, long resetTimePoint = 18000000L)
		{
			return BeginTimeOfMonth(now, resetTimePoint) + (long)GetTotalDaysInMonth(now) * 86400000L;
		}

		public static long GetDurationToEndMonth(long now, long resetTimePoint = 18000000L)
		{
			return EndTimeOfMonth(now, resetTimePoint) - now;
		}

		public static bool IsSameYear(long time1, long time2, long resetTimePoint = 18000000L)
		{
			time1 -= resetTimePoint;
			time2 -= resetTimePoint;
			DateTime dateTime = ToDateTime(time1);
			DateTime dateTime2 = ToDateTime(time2);
			return dateTime.Year == dateTime2.Year;
		}

		public static long GetYearEndTime()
		{
			DateTime dateTime = DateTimeNow();
			return (long)(dateTime.AddYears(1).AddMonths(-dateTime.Month).AddDays(-dateTime.Day)
				.AddHours(-dateTime.Hour)
				.AddMinutes(-dateTime.Minute)
				.AddSeconds(-dateTime.Second) - dateTime).TotalMilliseconds;
		}

		public static string TimeToString(long time)
		{
			double num = (double)time / 1000.0;
			if (num < 2592000.0)
			{
				if (num < 3600.0)
				{
					if (num < 60.0)
					{
						return $"{Math.Floor(num)}秒前";
					}
					return $"{Math.Floor(num / 60.0)}分前";
				}
				if (num < 86400.0)
				{
					return $"{Math.Floor(num / 3600.0)}时前";
				}
				return $"{Math.Floor(num / 86400.0)}天前";
			}
			if (num < 31536000.0)
			{
				return $"{Math.Floor(num / 2592000.0)}月前";
			}
			double d = num / 31536000.0;
			return $"{Math.Floor(d)}年前";
		}

		public static (int round, long startTime, long endTime) IsInTimeInterval(Hours[] hours)
		{
			for (int i = 0; i < hours.Length; i++)
			{
				Hours obj = hours[i];
				DateTime.TryParseExact(obj.StartTime, "HH:mm:ss", CultureInfo.InvariantCulture, DateTimeStyles.None, out var result);
				DateTime.TryParseExact(obj.EndTime, "HH:mm:ss", CultureInfo.InvariantCulture, DateTimeStyles.None, out var result2);
				if (Now() >= ToTime(result) && Now() < ToTime(result2))
				{
					return (round: i, startTime: ToTime(result), endTime: ToTime(result2));
				}
			}
			DateTime.TryParseExact(hours[0].StartTime, "HH:mm:ss", CultureInfo.InvariantCulture, DateTimeStyles.None, out var result3);
			DateTime.TryParseExact(hours[^1].EndTime, "HH:mm:ss", CultureInfo.InvariantCulture, DateTimeStyles.None, out var result4);
			return (round: -1, startTime: ToTime(result3), endTime: ToTime(result4));
		}

		public static (long startTime, long endTime) HoursToTodayLong(Hours hours)
		{
			DateTime.TryParseExact(hours.StartTime, "HH:mm:ss", CultureInfo.InvariantCulture, DateTimeStyles.None, out var result);
			DateTime.TryParseExact(hours.EndTime, "HH:mm:ss", CultureInfo.InvariantCulture, DateTimeStyles.None, out var result2);
			return (startTime: ToTime(result), endTime: ToTime(result2));
		}

		public static (long startTime, long endTime) HoursToZeroLong(Hours hours)
		{
			long item = (long)TimeSpan.Parse(hours.StartTime).TotalSeconds * 1000;
			long item2 = (long)TimeSpan.Parse(hours.EndTime).TotalSeconds * 1000;
			return (startTime: item, endTime: item2);
		}

		public static long StringTimeToLong(string time, long resetTimePoint = 18000000L)
		{
			return StringTimeToLongAtTime(time, ServerNow(), resetTimePoint);
		}

		public static long StringTimeToLongAtTime(string time, long baseTimestamp, long resetTimePoint = 18000000L)
		{
			if (!DateTime.TryParseExact(time, "HH:mm:ss", CultureInfo.InvariantCulture, DateTimeStyles.None, out var result))
			{
				return 0L;
			}
			DateTime dateTime = ToDateTime(baseTimestamp);
			long num = resetTimePoint / 3600000;
			int hour = result.Hour;
			DateTime dateTime2 = ((dateTime.Hour < num) ? ((hour < num) ? dateTime.Date : dateTime.AddDays(-1.0).Date) : ((hour >= num) ? dateTime.Date : dateTime.AddDays(1.0).Date));
			return ToTime(new DateTime(dateTime2.Year, dateTime2.Month, dateTime2.Day, result.Hour, result.Minute, result.Second));
		}
	}
