	public class ChatRobotHandlerAttribute : BaseAttribute
	{
		public readonly int Type;

		public ChatRobotHandlerAttribute(int type)
		{
			Type = type;
		}
	}
	public abstract class AChatRobotHandler
	{
		public int Type;

		public virtual int IsMeet(Player player, ChatRobotTriggerParam param)
		{
			foreach (ChatRobotTriggerConfig item in ConfigSingleton<ChatRobotTriggerConfigCategory>.Instance.GetConfigByType(param.Type))
			{
				if (item.TriggerPara.Contains(param.Value))
				{
					return item.Id;
				}
			}
			return -1;
		}

		public void CreateChatRobot(Scene scene, Player player, ChatRobotTriggerParam param, int configId)
		{
			ChatRobotTriggerConfig chatRobotTriggerConfig = ConfigSingleton<ChatRobotTriggerConfigCategory>.Instance.Get(configId);
			if (chatRobotTriggerConfig != null)
			{
				OnCreateChatRobot(scene, player, param, chatRobotTriggerConfig);
			}
		}

		protected virtual async void OnCreateChatRobot(Scene scene, Player player, ChatRobotTriggerParam param, ChatRobotTriggerConfig configId)
		{
			await ETTask.CompletedTask;
		}
	}
