	[GMCommand]
	public abstract class AGMCommand
	{
		public abstract void Execute(Player player, GMCommandParams ps);
	}
	public class GMCommandParams
	{
		private string[] parameters;

		private int index;

		public GMCommandParams(string[] parameters)
		{
			this.parameters = parameters;
		}

		public int PopInt()
		{
			int result = 0;
			string valueOrDefault = parameters.GetValueOrDefault(index++);
			if (!string.IsNullOrEmpty(valueOrDefault))
			{
				int.TryParse(valueOrDefault, out result);
			}
			return result;
		}

		public string PopString()
		{
			string valueOrDefault = parameters.GetValueOrDefault(index++);
			if (!string.IsNullOrEmpty(valueOrDefault))
			{
				return valueOrDefault;
			}
			return string.Empty;
		}
	}
