	public class LocalData
	{
		private Dictionary<string, object> objectCache = new Dictionary<string, object>();

		private static LocalData instance { get; } = new LocalData();

		public static void SetString(string key, string value)
		{
			PlayerPrefs.SetString(key, value);
		}

		public static string GetString(string key, string defaultValue = null)
		{
			return PlayerPrefs.GetString(key, defaultValue);
		}

		public static void SetInt(string key, int value)
		{
			PlayerPrefs.SetInt(key, value);
		}

		public static int GetInt(string key, int defaultValue = 0)
		{
			return PlayerPrefs.GetInt(key, defaultValue);
		}

		public static void SetData<T>(string key, T data) where T : class, new()
		{
			string text = JsonHelper.ToJson((object)data);
			PlayerPrefs.SetString(key, text);
			instance.objectCache[key] = data;
		}

		public static T GetData<T>(string key) where T : class, new()
		{
			if (!instance.objectCache.TryGetValue(key, out var value))
			{
				string text = PlayerPrefs.GetString(key);
				value = ((!string.IsNullOrEmpty(text)) ? JsonHelper.FromJson<T>(text) : new T());
				instance.objectCache.Add(key, value);
			}
			return value as T;
		}
	}
