	public static class PlayerLocalData
	{
		private static string GetCombineKey(Player player, string key)
		{
			return key + ((Entity)player).Id;
		}

		public static T GetLocalData<T>(this Player player) where T : class, new()
		{
			if (player == null)
			{
				return null;
			}
			return LocalData.GetData<T>(GetCombineKey(player, typeof(T).Name));
		}

		public static void SetLocalData<T>(this Player player, T data) where T : class, new()
		{
			if (player != null)
			{
				LocalData.SetData(GetCombineKey(player, typeof(T).Name), data);
			}
		}

		public static bool GetLocalBool(this Player player, string key, bool @default = false)
		{
			if (player == null)
			{
				return @default;
			}
			return PlayerPrefs.GetInt(GetCombineKey(player, key), @default ? 1 : 0) >= 1;
		}

		public static void SetLocalBool(this Player player, string key, bool value)
		{
			if (player != null)
			{
				PlayerPrefs.SetInt(GetCombineKey(player, key), value ? 1 : 0);
			}
		}

		public static int GetLocalInt(this Player player, string key, int defaultValue = 0)
		{
			if (player == null)
			{
				return defaultValue;
			}
			return PlayerPrefs.GetInt(GetCombineKey(player, key), defaultValue);
		}

		public static void SetLocalInt(this Player player, string key, int value)
		{
			if (player != null)
			{
				PlayerPrefs.SetInt(GetCombineKey(player, key), value);
			}
		}

		public static string GetLocalString(this Player player, string key, string defaultValue = null)
		{
			if (player == null)
			{
				return defaultValue;
			}
			return PlayerPrefs.GetString(GetCombineKey(player, key), defaultValue);
		}

		public static void SetLocalString(this Player player, string key, string value)
		{
			if (player != null)
			{
				PlayerPrefs.SetString(GetCombineKey(player, key), value);
			}
		}

		public static long GetLocalLong(this Player player, string key, long defaultValue = 0L)
		{
			if (player == null)
			{
				return defaultValue;
			}
			long.TryParse(PlayerPrefs.GetString(GetCombineKey(player, key), defaultValue.ToString()), out var result);
			return result;
		}

		public static void SetLocalLong(this Player player, string key, long value)
		{
			if (player != null)
			{
				PlayerPrefs.SetString(GetCombineKey(player, key), value.ToString());
			}
		}
	}
