		{
			RedPointType = redPointType;
			RedPointArgs = redPointArgs;
			return this;
		}

		public UITabInfo SetRedPointArgs(params int[] redPointArgs)
		{
			RedPointArgs = redPointArgs;
			return this;
		}

		public UITabInfo SetBackGroup(string icon)
		{
			BackGroup = icon;
			return this;
		}

		public UITabInfo SetIcon(string icon, string iconEffect = null)
		{
			Icon = icon;
			IconEffect = iconEffect;
			return this;
