	[ComponentOf(typeof(UIObject))]
	public class UIScrollListCell : Entity, IAwake
	{
		public int _Index;

		private UIScrollList scrollList;

		public UIObject UIObject => ((Entity)this).GetParent<UIObject>();

		public int Index => _Index;

		public UIScrollList ScrollList => scrollList ?? (scrollList = ((Entity)((Entity)UIObject).GetParent<UIObject>()).GetComponent<UIScrollList>());

		public bool IsSelected => ScrollList.CurrentSelectIndex == Index;
	}
	public class UIScrollListHandler
	{
		public event Action<UIScrollListCell> onCreate;

		public event Action<UIScrollListCell> onUpdate;

		public void Clear()
		{
			onCreate = null;
			onUpdate = null;
		}

		public void Create(UIScrollListCell cell)
		{
			onCreate?.Invoke(cell);
		}

		public void Update(UIScrollListCell cell)
		{
			if (onUpdate == null)
			{
				return;
			}
			try
			{
				onUpdate(cell);
			}
			catch (Exception ex)
			{
				Log.Error(ex);
			}
		}
	}
