	public struct UITimerHandler
	{
		public Action Action;
	}
	[FriendOf(typeof(UITimerComponent))]
	[ChildOf(typeof(UITimerComponent))]
	public class UITimer : Entity, IAwake<Action, bool>, IDestroy
	{
		public long TimerId;

		public bool Repeat;

		public UITimerHandler Handler;
	}
	[FriendOf(typeof(UITimer))]
	public static class UITimerSystem
	{
		public class AwakeSystem : AwakeSystem<UITimer, Action, bool>
		{
			protected override void Awake(UITimer self, Action a, bool b)
			{
				self.Handler = new UITimerHandler
				{
					Action = a
				};
				self.Repeat = b;
			}
		}

		public class DestroySystem : DestroySystem<UITimer>
		{
			protected override void Destroy(UITimer self)
			{
				Singleton<TimerComponent>.Instance.Remove(ref self.TimerId);
				self.Handler = default(UITimerHandler);
				self.Repeat = false;
			}
		}

		public static void Invoke(this UITimer self)
		{
			self.Handler.Action?.Invoke();
		}
	}
	[ComponentOf(typeof(UIObject))]
	public class UITimerComponent : Entity, IAwake, IDestroy
	{
		public long IdGenerater;
	}
