	public static class UIEffectHelper
	{
		[StaticField]
		private static readonly string[] ItemQualityEffect = new string[3] { "ui_fx_tongyongdaoju_1", "ui_fx_tongyongdaoju_2", "ui_fx_tongyongdaoju_3" };

		public static string GetQualityEffect(int quality)
		{
			int num = quality - 5;
			if (num < 0 || num >= ItemQualityEffect.Length)
			{
				return null;
			}
			return ItemQualityEffect[num];
		}
	}
